package com.badworldwarning;

import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.annotation.Nullable;
import lombok.Getter;
import net.runelite.api.WorldType;

enum BadWorldType
{
	BLAST_FURNACE("Blast Furnace", BadWorldWarningConfig::blastFurnace, "blast furnace"),
	CASTLE_WARS("Castle Wars", BadWorldWarningConfig::castleWars, "castle wars"),
	FORESTRY("Forestry", BadWorldWarningConfig::forestry, "forestry"),
	GUARDIANS_OF_THE_RIFT("GotR", BadWorldWarningConfig::guardiansOfTheRift, "guardians of the rift", "gotr"),
	HIGH_RISK("High Risk", BadWorldWarningConfig::highRisk, WorldType.HIGH_RISK),
	HOUSE_PARTY("House Party", BadWorldWarningConfig::houseParty, "house party", "gilded altar"),
	PEST_CONTROL("Pest Control", BadWorldWarningConfig::pestControl, "pest control"),
	SALVAGING("Salvaging", BadWorldWarningConfig::salvaging, "salvaging"),
	TEMPOROSS("Tempoross", BadWorldWarningConfig::tempoross, "tempoross"),
	TRADE("Trade", BadWorldWarningConfig::trade, "trade"),
	WINTERTODT("Wintertodt", BadWorldWarningConfig::wintertodt, "wintertodt");

	@Getter
	private final String displayName;
	private final Predicate<BadWorldWarningConfig> enabled;
	@Nullable
	private final WorldType flag;
	@Nullable
	private final Pattern pattern;

	BadWorldType(String displayName, Predicate<BadWorldWarningConfig> enabled, WorldType flag)
	{
		this.displayName = displayName;
		this.enabled = enabled;
		this.flag = flag;
		this.pattern = null;
	}

	BadWorldType(String displayName, Predicate<BadWorldWarningConfig> enabled, String... words)
	{
		this.displayName = displayName;
		this.enabled = enabled;
		this.flag = null;
		this.pattern = Pattern.compile(
			Stream.of(words).map(Pattern::quote).collect(Collectors.joining("|", "\\b(?:", ")\\b")),
			Pattern.CASE_INSENSITIVE);
	}

	boolean isEnabled(BadWorldWarningConfig config)
	{
		return enabled.test(config);
	}

	boolean matches(Set<WorldType> worldTypes, String activity)
	{
		return flag != null ? worldTypes.contains(flag) : pattern.matcher(activity).find();
	}
}

