package com.badworldwarning;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class BadWorldWarningOverlay extends OverlayPanel
{
	private static final String BAD_WORLD_TEXT = "BAD WORLD";

	private final BadWorldWarningPlugin plugin;
	private final BadWorldWarningConfig config;
	private Font warningFont;

	@Inject
	private BadWorldWarningOverlay(BadWorldWarningPlugin plugin, BadWorldWarningConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String reason = plugin.getBadWorldReason();
		if (reason == null)
		{
			return null;
		}

		graphics.setFont(warningFont);
		int width = graphics.getFontMetrics().stringWidth(BAD_WORLD_TEXT);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(BAD_WORLD_TEXT)
			.color(config.warningColor())
			.build());

		if (config.showReasons())
		{
			Font reasonFont = FontManager.getRunescapeFont();
			FontMetrics reasonMetrics = graphics.getFontMetrics(reasonFont);
			width = Math.max(width, reasonMetrics.stringWidth(reason));
			panelComponent.getChildren().add(LineComponent.builder()
				.left(reason)
				.leftFont(reasonFont)
				.build());
		}

		panelComponent.setPreferredSize(new Dimension(width + ComponentConstants.STANDARD_BORDER * 2, 0));
		return super.render(graphics);
	}

	void updateConfig()
	{
		warningFont = FontManager.getRunescapeFont().deriveFont((float) config.fontSize());
	}
}

