import net.runelite.client.util.Text;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldRegion;
import net.runelite.http.api.worlds.WorldResult;

@Slf4j
@PluginDescriptor(
	name = "Bad World Warning",
	description = "Warns you when you're on a bad world (by region, activity, custom list, or population)",
	tags = {"world", "worlds", "region", "regions", "location", "locations", "population", "warning", "ping"}
)
public class BadWorldWarningPlugin extends Plugin
{
	private static final int LOCATION_US_WEST = -73;
	private static final int LOCATION_US_EAST = -42;

	private static final Splitter WORLD_SPLITTER = Splitter.onPattern("[,\\s]+").omitEmptyStrings();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private WorldService worldService;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BadWorldWarningOverlay overlay;

	@Inject
	private BadWorldWarningConfig config;

	@Getter(AccessLevel.PACKAGE)
	@Nullable
	private String badWorldReason;

	@Nullable
	private WorldResult worlds;

	private Map<Integer, Integer> switcherPlayerCounts = Collections.emptyMap();

	@Override
	protected void startUp()
	{
		overlay.updateConfig();
		overlayManager.add(overlay);
		clientThread.invoke(this::checkWorld);
		executor.execute(() ->
		{
			WorldResult worldResult = worldService.getWorlds();
			clientThread.invoke(() ->
			{
				worlds = worldResult;
				checkWorld();
			});
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		badWorldReason = null;
		worlds = null;
		switcherPlayerCounts = Collections.emptyMap();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			checkWorld();
		}
	}

	@Subscribe
	public void onWorldsFetch(WorldsFetch event)
	{
		clientThread.invoke(() ->
		{
			worlds = event.getWorldResult();
			switcherPlayerCounts = Collections.emptyMap();
			checkWorld();
		});
	}

	@Subscribe
	public void onWorldListLoad(WorldListLoad event)
	{
		Map<Integer, Integer> playerCounts = new HashMap<>();
		for (net.runelite.api.World world : event.getWorlds())
		{
			playerCounts.put(world.getId(), world.getPlayerCount());
		}

		switcherPlayerCounts = playerCounts;
		checkWorld();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BadWorldWarningConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		overlay.updateConfig();
		clientThread.invoke(this::checkWorld);
	}

	private void checkWorld()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			badWorldReason = null;
			return;
		}

		int worldId = client.getWorld();
		EnumSet<WorldType> worldTypes = client.getWorldType();
		World world = findWorld(worldId);
		String activity = world == null ? "" : Strings.nullToEmpty(world.getActivity());
		List<String> reasons = new ArrayList<>();

		if (isBadWorld(worldId))
		{
			reasons.add("Bad world list");
		}

		String uncheckedRegion = world == null ? null : uncheckedRegionName(world);
		if (uncheckedRegion != null)
		{
			reasons.add(uncheckedRegion);
		}

		for (BadWorldType type : BadWorldType.values())
		{
			if (type.isEnabled(config) && type.matches(worldTypes, activity))
			{
				reasons.add(type.getDisplayName());
			}
		}

		if (config.highPop() && playerCount(worldId, world) > config.highPopThreshold())
		{
			reasons.add("High Pop");
		}

		log.debug("World {} ({}): {}", worldId, activity, reasons);
		badWorldReason = reasons.isEmpty() ? null : String.join(", ", reasons);
	}

	@Nullable
	private World findWorld(int worldId)
	{
		return worlds == null ? null : worlds.findWorld(worldId);
	}

	private int playerCount(int worldId, @Nullable World world)
	{
		Integer switcherPlayerCount = switcherPlayerCounts.get(worldId);
		if (switcherPlayerCount != null)
		{
			return switcherPlayerCount;
		}
		return world == null ? -1 : world.getPlayers();
	}

	private boolean isBadWorld(int worldId)
	{
		String world = Integer.toString(worldId);
		for (String badWorld : WORLD_SPLITTER.split(config.badWorlds()))
		{
			if (badWorld.equals(world))
			{
				return true;
			}
		}
		return false;
	}

	@Nullable
	private String uncheckedRegionName(World world)
	{
		WorldRegion region = world.getRegion();
		if (region == null)
		{
			return "Unknown";
		}

		switch (region)
		{
			case UNITED_STATES_OF_AMERICA:
				switch (client.getEnum(EnumID.WORLD_LOCATIONS).getIntValue(world.getId()))
				{
					case LOCATION_US_EAST:
						return config.usEast() ? null : "US East";
					case LOCATION_US_WEST:
						return config.usWest() ? null : "US West";
					default:
						return config.usEast() || config.usWest() ? null : "US";
				}
			case UNITED_KINGDOM:
				return config.unitedKingdom() ? null : "UK";
			case GERMANY:
				return config.germany() ? null : "German";
			case AUSTRALIA:
				return config.australia() ? null : "Australian";
			case BRAZIL:
				return config.brazil() ? null : "Brazilian";
			case JAPAN:
				return config.japan() ? null : "Japanese";
			case SINGAPORE:
				return config.singapore() ? null : "Singaporean";
			case SOUTH_AFRICA:
				return config.southAfrica() ? null : "South African";
			default:
				return Text.titleCase(region);
		}
	}

	@Provides
	BadWorldWarningConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BadWorldWarningConfig.class);
	}
}
